/**
 * Init in-memory queue + seen set for this governed run.
 * Cross-run dedupe: wire a Sheets Read beforehand and pass known job_ids into seen.
 */
const cfg = items[0].json;
const seed = String(cfg.seed_url || '').trim();
if (!seed || !/linkedin\.com\/jobs\/view\//i.test(seed)) {
  throw new Error('seed_url must be a LinkedIn /jobs/view/ guest URL');
}

function jobIdFromUrl(url) {
  const m = String(url).match(/\/jobs\/view\/[^/?#]*?(\d{6,})(?:[/?#]|$)/i);
  return m ? m[1] : null;
}

const seedId = jobIdFromUrl(seed) || `seed-${Date.now()}`;
const staticData = $getWorkflowStaticData('global');
staticData.crawl = {
  seed_url: seed,
  max_hops: Number(cfg.max_hops) || 2,
  max_pages: Number(cfg.max_pages) || 25,
  coffee_every: Number(cfg.coffee_every) || 12,
  pages_fetched: 0,
  abnormal_streak: 0,
  seen: { [seedId]: true },
  queue: [{ url: seed.split('?')[0], hop: 0, job_id: seedId, discovered_from_job_id: '' }],
  started_at: new Date().toISOString(),
};

return [{ json: { ok: true, seed_url: seed, seed_job_id: seedId, queue_len: 1 } }];

/** Pop next queued URL under governor. Dedupe is at enqueue-time (seen), not at pop. */
const staticData = $getWorkflowStaticData('global');
const crawl = staticData.crawl;
if (!crawl) throw new Error('Crawl state missing — run Init Queue first');

if (crawl.pages_fetched >= crawl.max_pages) {
  return [{ json: { has_next: false, reason: 'max_pages', pages_fetched: crawl.pages_fetched } }];
}

while (crawl.queue.length) {
  const next = crawl.queue.shift();
  if (!next || !next.url) continue;
  if (Number(next.hop) > Number(crawl.max_hops)) continue;
  return [{
    json: {
      has_next: true,
      url: next.url,
      hop: Number(next.hop) || 0,
      job_id: next.job_id || '',
      discovered_from_job_id: next.discovered_from_job_id || '',
      pages_fetched: crawl.pages_fetched,
      queue_remaining: crawl.queue.length,
      max_hops: crawl.max_hops,
      max_pages: crawl.max_pages,
      coffee_every: crawl.coffee_every,
      seed_url: crawl.seed_url,
    },
  }];
}

return [{ json: { has_next: false, reason: 'queue_empty', pages_fetched: crawl.pages_fetched } }];

/** Classify LinkedIn guest response for back-off logic. */
const prev = $('Pop Next URL').item.json;
const res = items[0].json;
const status = Number(res.statusCode || res.status || 0);
const body = String(res.body ?? res.data ?? '');
const ms = Number(res.headers && (res.headers['x-n8n-duration'] || 0)) || 0;

const empty = body.length < 800;
const authwall = /join linkedin|sign in|authwall|challenge/i.test(body);
const abnormal =
  status === 0 ||
  status >= 400 ||
  empty ||
  authwall ||
  !/application\/ld\+json|base-card|job-details/i.test(body);

return [{
  json: {
    ...prev,
    statusCode: status,
    body_len: body.length,
    html: body,
    abnormal,
    abnormal_reason: abnormal
      ? (status >= 400 ? `http_${status}` : empty ? 'empty_body' : authwall ? 'authwall' : 'missing_markers')
      : '',
    fetch_attempt: 1,
  },
}];

const prev = $('Classify Response').item.json;
const res = items[0].json;
const status = Number(res.statusCode || res.status || 0);
const body = String(res.body ?? res.data ?? '');
const empty = body.length < 800;
const authwall = /join linkedin|sign in|authwall|challenge/i.test(body);
const abnormal =
  status === 0 ||
  status >= 400 ||
  empty ||
  authwall ||
  !/application\/ld\+json|base-card|job-details/i.test(body);

return [{
  json: {
    ...prev,
    statusCode: status,
    body_len: body.length,
    html: body,
    abnormal,
    abnormal_reason: abnormal
      ? (status >= 400 ? `http_${status}` : empty ? 'empty_body' : authwall ? 'authwall' : 'missing_markers')
      : '',
    fetch_attempt: 2,
  },
}];

/** Step 3a — Parse contract-grade JobPosting from JSON-LD. */
const extracted = items[0].json;
// ctx fields (url/hop/...) ride through from Classify*; extract adds jsonld + similar_raw
const ctx = extracted;
let blocks = extracted.jsonld;
if (!Array.isArray(blocks)) blocks = blocks ? [blocks] : [];

function parseMaybeJson(s) {
  if (s == null) return null;
  if (typeof s === 'object') return s;
  try { return JSON.parse(String(s)); } catch { return null; }
}

let posting = null;
for (const b of blocks) {
  const obj = parseMaybeJson(b);
  if (!obj) continue;
  const candidates = Array.isArray(obj) ? obj : (obj['@graph'] || [obj]);
  for (const c of candidates) {
    const t = c && c['@type'];
    const types = Array.isArray(t) ? t : [t];
    if (types.map(String).some((x) => /JobPosting/i.test(x))) {
      posting = c;
      break;
    }
  }
  if (posting) break;
}

function jobIdFromUrl(url) {
  const m = String(url || '').match(/\/jobs\/view\/[^/?#]*?(\d{6,})(?:[/?#]|$)/i);
  return m ? m[1] : null;
}

function companySlug(url) {
  const m = String(url || '').match(/linkedin\.com\/company\/([^/?#]+)/i);
  return m ? decodeURIComponent(m[1]) : '';
}

function companyHost(url) {
  try {
    return new URL(url).host.toLowerCase();
  } catch {
    return '';
  }
}

function founderHint(desc) {
  const text = String(desc || '');
  const patterns = [
    /report(?:ing)? to\s+([A-Z][a-z]+(?:\s+[A-Z][a-z]+){0,2})/,
    /founded by\s+([A-Z][a-z]+(?:\s+[A-Z][a-z]+){0,2})/i,
    /CEO[,\s]+([A-Z][a-z]+(?:\s+[A-Z][a-z]+){0,2})/,
  ];
  for (const re of patterns) {
    const m = text.match(re);
    if (m) return m[1];
  }
  return '';
}

const org = (posting && posting.hiringOrganization) || {};
const loc = (posting && posting.jobLocation) || {};
const place = (loc && loc.address) || loc || {};
const geo = (loc && loc.geo) || {};
const exp = (posting && posting.experienceRequirements) || {};
const months = exp.monthsOfExperience ?? exp.months_of_experience ?? '';

const url = ctx.url;
const job_id = ctx.job_id || jobIdFromUrl(url) || jobIdFromUrl(posting && posting.url) || '';
const companyUrl = org.sameAs || org.url || '';

const primary = {
  job_id,
  source: 'linkedin',
  fidelity: 'primary',
  url,
  title: (posting && posting.title) || '',
  description: (posting && posting.description) || '',
  employment_type: (posting && posting.employmentType) || '',
  date_posted: (posting && posting.datePosted) || '',
  valid_through: (posting && posting.validThrough) || '',
  location: place.addressLocality
    || place.addressRegion
    || [place.addressLocality, place.addressRegion, place.addressCountry].filter(Boolean).join(', ')
    || (typeof place === 'string' ? place : ''),
  geo_lat: geo.latitude || '',
  geo_lng: geo.longitude || '',
  months_of_experience: months,
  founder_or_report_line: founderHint(posting && posting.description),
  company_name: org.name || '',
  company_linkedin_url: companyUrl,
  company_slug: companySlug(companyUrl),
  company_host: companyHost(companyUrl),
  salary_raw: '',
  hop: ctx.hop,
  scraped_at: new Date().toISOString(),
  seed_url: ctx.seed_url,
  discovered_from_job_id: ctx.discovered_from_job_id || '',
  parse_ok: Boolean(posting),
};

return [{
  json: {
    ctx,
    similar_raw: extracted.similar_raw || [],
    primary,
  },
}];

/** Step 3b — Harvest similar-jobs / people-also-viewed cards (lower fidelity). */
const input = items[0].json;
const cards = Array.isArray(input.similar_raw) ? input.similar_raw : (input.similar_raw ? [input.similar_raw] : []);
const parentId = input.primary.job_id;
const parentHop = Number(input.ctx.hop) || 0;

function jobIdFromUrl(url) {
  const m = String(url || '').match(/\/jobs\/view\/[^/?#]*?(\d{6,})(?:[/?#]|$)/i);
  return m ? m[1] : null;
}

function absUrl(href) {
  if (!href) return '';
  if (/^https?:\/\//i.test(href)) return href.split('?')[0];
  if (href.startsWith('/')) return `https://www.linkedin.com${href.split('?')[0]}`;
  return '';
}

function firstMatch(html, re) {
  const m = String(html).match(re);
  return m ? (m[1] || '').trim() : '';
}

function companySlug(url) {
  const m = String(url || '').match(/linkedin\.com\/company\/([^/?#]+)/i);
  return m ? decodeURIComponent(m[1]) : '';
}

function companyHost(url) {
  try { return new URL(url).host.toLowerCase(); } catch { return ''; }
}

const discoveries = [];
for (const raw of cards) {
  const html = String(raw || '');
  if (!html) continue;
  const href = firstMatch(html, /href="([^"]*\/jobs\/view\/[^"]+)"/i)
    || firstMatch(html, /href='([^']*\/jobs\/view\/[^']+)'/i);
  const url = absUrl(href.replace(/&amp;/g, '&'));
  const job_id = jobIdFromUrl(url);
  if (!url || !job_id) continue;
  if (job_id === parentId) continue;

  const companyHref = absUrl(
    (firstMatch(html, /href="([^"]*linkedin\.com\/company\/[^"]+)"/i) ||
      firstMatch(html, /href="(\/company\/[^"]+)"/i)).replace(/&amp;/g, '&')
  );
  const company_name =
    firstMatch(html, /base-search-card__subtitle[^>]*>([\s\S]*?)<\//i).replace(/<[^>]+>/g, '').trim()
    || firstMatch(html, /hidden-nested-link[^>]*>([\s\S]*?)<\//i).replace(/<[^>]+>/g, '').trim();
  const location =
    firstMatch(html, /job-search-card__location[^>]*>([\s\S]*?)<\//i).replace(/<[^>]+>/g, '').trim();
  const date_text =
    firstMatch(html, /datetime="([^"]+)"/i)
    || firstMatch(html, /job-search-card__listdate[^>]*>([\s\S]*?)<\//i).replace(/<[^>]+>/g, '').trim();
  const salary_raw =
    firstMatch(html, /job-search-card__salary-info[^>]*>([\s\S]*?)<\//i).replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim()
    || firstMatch(html, /(\$[\d,]+\s*[-–]\s*\$[\d,]+[^<]*)/i).replace(/\s+/g, ' ').trim();

  discoveries.push({
    job_id,
    url,
    hop: parentHop + 1,
    status: 'queued',
    discovered_from_job_id: parentId,
    company_name,
    company_slug: companySlug(companyHref),
    company_host: companyHost(companyHref) || (companyHref ? 'www.linkedin.com' : ''),
    company_linkedin_url: companyHref,
    location,
    date_text,
    salary_raw,
    fidelity: 'graph',
    source: 'linkedin',
    first_seen_at: new Date().toISOString(),
  });
}

return [{ json: { ...input, discoveries } }];

/** Step 4 — Stamp known gaps on primary + graph rows. */
function stamp(row, kind) {
  const gaps = [];
  const companyUrl = String(row.company_linkedin_url || '');
  if (!row.website) gaps.push('no_external_website');
  if (!companyUrl || /linkedin\.com\/company\//i.test(companyUrl)) {
    gaps.push('linkedin_internal_company_link_only');
  }
  if (row.company_slug) gaps.push('company_slug_may_be_historical');
  // industry often absent / stale on guest pages — flag for primary when we lack a clean external domain
  if (kind === 'primary') gaps.push('industry_may_be_stale_or_missing');
  if (kind === 'graph') {
    gaps.push('graph_best_effort_html');
    if (!row.salary_raw) gaps.push('salary_missing_on_card');
  }
  return { ...row, gaps: gaps.join('|') };
}

const input = items[0].json;
const primary = stamp({ ...input.primary, website: '' }, 'primary');
const discoveries = (input.discoveries || []).map((d) => stamp({ ...d, website: '' }, 'graph'));

return [{ json: { ctx: input.ctx, primary, discoveries } }];

/** Emit primary row for Sheets append. */
const { primary } = items[0].json;
return [{ json: primary }];

/**
 * Step 5b — Enqueue discoveries into static queue (dedupe on job_id).
 * Also emit only *new* graph rows for the Discovery Queue sheet.
 */
const bag = $('Stamp Known Gaps').item.json;
const staticData = $getWorkflowStaticData('global');
const crawl = staticData.crawl;
crawl.pages_fetched = (crawl.pages_fetched || 0) + 1;

const newForSheet = [];
for (const d of bag.discoveries || []) {
  const id = d.job_id;
  if (!id) continue;
  if (crawl.seen[id]) continue;
  crawl.seen[id] = true;
  if (Number(d.hop) <= Number(crawl.max_hops)) {
    crawl.queue.push({
      url: d.url,
      hop: d.hop,
      job_id: id,
      discovered_from_job_id: d.discovered_from_job_id,
    });
  }
  newForSheet.push({
    ...d,
    status: Number(d.hop) <= Number(crawl.max_hops) ? 'queued' : 'skipped',
  });
}

const coffeeEvery = Number(crawl.coffee_every) || 12;
const pages = crawl.pages_fetched;
const baseline = 4 + Math.random() * 5; // 4–9s
const needsCoffee = pages > 0 && pages % coffeeEvery === 0;
const coffee = needsCoffee ? 30 + Math.random() * 30 : 0; // 30–60s

return [{
  json: {
    pages_fetched: pages,
    newly_queued: newForSheet.length,
    queue_remaining: crawl.queue.length,
    wait_baseline_seconds: Math.round(baseline * 10) / 10,
    needs_coffee: needsCoffee,
    wait_coffee_seconds: Math.round(coffee),
    discoveries: newForSheet,
  },
}];

const { discoveries } = items[0].json;
if (!discoveries || !discoveries.length) {
  return [{ json: { _skip_sheet: true } }];
}
return discoveries.map((d) => ({ json: d }));

/** Re-load wait fields after Sheets fan-out (take first / from Enqueue node). */
const e = $('Enqueue + Schedule Waits').item.json;
return [{ json: e }];
